-- PREPARED ONLY; no execution has occurred. Pinned source: b6ee3973.
-- Execute only through staging project kubdiqdhqbhwmqfditeg after root verifies it.
-- Register the new manual fixture UUID in the durable ledger BEFORE executing.
-- Replace all four placeholders from the ledger; none is an invented runtime ID.
-- Browser journey 2 must have shown the expansion restriction and DECLINED that
-- pending Restore. A server-rejected Apply with failure_reason is not a decline.
BEGIN;
SET LOCAL lock_timeout = '5s';
SET LOCAL statement_timeout = '30s';
SELECT set_config('run_e.auth_id', 'ac02a2a9-98b7-4fdf-9957-560d387759e1'::uuid::text, true);
SELECT set_config('run_e.clear_id', '01a0a448-58b8-724e-b57c-5575f99bce29'::uuid::text, true);
SELECT set_config('run_e.declined_id', '0e879dbc-a085-40c5-8e77-8fa429b2af45'::uuid::text, true);
SELECT set_config('run_e.manual_policy_id', '019f43e0-0000-7000-8000-000000000014'::uuid::text, true);

DO $fixture$
DECLARE
 account_uuid constant uuid := '019f43e0-0000-7000-8000-000000000001';
 actor_uuid constant uuid := '019f43e0-0000-7000-8000-000000000002';
 cafe_uuid constant uuid := '019f43e0-0000-7000-8000-000000000012';
 source_row public.agent_proposals%ROWTYPE;
 declined_row public.agent_proposals%ROWTYPE;
BEGIN
 -- Match the production lifecycle lock order: location before account, then proposal.
 PERFORM id FROM public.businesses
 WHERE id=cafe_uuid AND account_id=account_uuid AND name='Cafe'
   AND display_label='Cafe' AND owner_email='run-e-019f43e0@e2e.repworth.net'
   AND onboarded_by=actor_uuid AND archived_at IS NULL
 FOR NO KEY UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Exact synthetic Cafe guard failed'; END IF;
 PERFORM id FROM public.accounts
 WHERE id=account_uuid AND owner_user_id=actor_uuid
   AND display_name='Run E Synthetic Account'
   AND subscription_tier='autopilot' AND subscription_status='active'
   AND stripe_customer_id IS NULL AND stripe_subscription_id IS NULL
 FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Exact synthetic account guard failed'; END IF;
 PERFORM u.id FROM public.users u JOIN auth.users a ON a.id::text=u.auth_id
 WHERE u.id=actor_uuid AND u.account_id=account_uuid AND u.role='owner'
   AND u.name='Run E Synthetic Owner' AND u.email='run-e-019f43e0@e2e.repworth.net'
   AND a.id=current_setting('run_e.auth_id')::uuid AND a.email=u.email
 FOR SHARE OF u,a;
 IF NOT FOUND THEN RAISE EXCEPTION 'Exact synthetic actor/Auth guard failed'; END IF;

 SELECT * INTO STRICT source_row FROM public.agent_proposals
 WHERE id=current_setting('run_e.clear_id')::uuid AND account_id=account_uuid
   AND location_id=cafe_uuid AND actor_user_id=actor_uuid
 FOR UPDATE;
 IF source_row.status IS DISTINCT FROM 'applied'
   OR source_row.operation IS DISTINCT FROM 'clear_location_override'
   OR source_row.contract_version IS DISTINCT FROM 1
   OR source_row.decided_by_user_id IS DISTINCT FROM actor_uuid
   OR source_row.applied_at IS NULL OR source_row.receipt IS NULL
   OR source_row.receipt->'scope' IS DISTINCT FROM jsonb_build_object('accountId',account_uuid,'locationId',cafe_uuid)
   OR source_row.receipt->>'actorUserId' IS DISTINCT FROM actor_uuid::text
   OR source_row.receipt->'before'->'rowExists' IS DISTINCT FROM 'true'::jsonb
   OR source_row.receipt->'before'->'threshold' IS DISTINCT FROM '5'::jsonb
   OR source_row.receipt->'before'->'vetoWindowMinutes' IS DISTINCT FROM '30'::jsonb
   OR source_row.receipt->'before'->'dailyAutoPostCap' IS DISTINCT FROM '2'::jsonb
   OR source_row.receipt->'after'->'rowExists' IS DISTINCT FROM 'false'::jsonb
 THEN RAISE EXCEPTION 'Journey 2 genuine applied Cafe clear receipt guard failed'; END IF;

 SELECT * INTO STRICT declined_row FROM public.agent_proposals
 WHERE id=current_setting('run_e.declined_id')::uuid AND account_id=account_uuid
   AND location_id=cafe_uuid AND actor_user_id=actor_uuid
 FOR UPDATE;
 IF declined_row.input IS DISTINCT FROM jsonb_build_object('restore',jsonb_build_object('sourceProposalId',source_row.id))
   OR declined_row.operation IS DISTINCT FROM source_row.operation
   OR declined_row.status IS DISTINCT FROM 'rejected'
   OR declined_row.decided_by_user_id IS DISTINCT FROM actor_uuid
   OR declined_row.failure_reason IS NOT NULL
   OR declined_row.applied_at IS NOT NULL OR declined_row.receipt IS NOT NULL
   OR NOT COALESCE(declined_row.after->'expansionBlockedBy' ? 'auto_approval_disabled',false)
 THEN RAISE EXCEPTION 'Journey 2 blocked Restore was not explicitly declined'; END IF;

 IF EXISTS(SELECT 1 FROM public.agent_turns WHERE account_id=account_uuid AND status IN ('accepted','running'))
   OR EXISTS(SELECT 1 FROM public.agent_proposals WHERE account_id=account_uuid AND location_id=cafe_uuid AND status='pending')
 THEN RAISE EXCEPTION 'Stop submissions and settle all work before synthetic manual setup'; END IF;
 -- No account default or location Reply policy should remain after journey 2.
 -- Never erase a suspension or overwrite a replacement policy to make this pass.
 IF EXISTS(SELECT 1 FROM public.auto_approval_policies WHERE account_id=account_uuid AND persona='reply' AND action_class='posting')
   OR EXISTS(SELECT 1 FROM public.auto_approval_policies WHERE id=current_setting('run_e.manual_policy_id')::uuid)
 THEN RAISE EXCEPTION 'Expected Reply-policy absence or new fixture UUID guard failed'; END IF;

 INSERT INTO public.auto_approval_policies
   (id,account_id,location_id,persona,action_class,auto_approve_min_star,veto_window_minutes,daily_auto_post_cap)
 VALUES (current_setting('run_e.manual_policy_id')::uuid,account_uuid,cafe_uuid,'reply','posting',NULL,30,2);
 -- Only a labeled SQL fixture. No applied receipt, audit, refusal or suspension is fabricated.
END $fixture$;
SELECT id,account_id,location_id,persona,action_class,auto_approve_min_star,
 veto_window_minutes,daily_auto_post_cap,suspended_at::text,suspended_reason,
 created_at::text,updated_at::text
FROM public.auto_approval_policies
WHERE id=current_setting('run_e.manual_policy_id')::uuid
 AND account_id='019f43e0-0000-7000-8000-000000000001';
COMMIT;
